"""Synthetic SPEC 5.5 timelines. This writes only the neighboring fixture file."""
import json
from pathlib import Path

cases = []

def step(at, state, kind=None, source="hook", confidence="exact", **kw):
    s = dict(at=at, state=state)
    if kind:
        s["event"] = dict(kind=kind, source=source, confidence=confidence)
    s.update(kw)
    return s

def case(name, steps, counts=None, tool="claude"):
    cases.append(dict(name=name, tool=tool, steps=steps, counts=counts or {}))

case("session_start_floor", [step(0,"starting","session_start"),step(1999,"starting"),step(2000,"starting")], {"sessions":1})
case("process_start_floor", [step(0,"starting","process_up","process","inferred"),step(100,"starting","turn_start"),step(1999,"starting"),step(2000,"working")], {"sessions":1})
case("new_turn_has_no_start_floor", [step(0,"working","turn_start"),step(1000,"working")])
case("start_then_work", [step(0,"starting","session_start"),step(2000,"working","turn_start")], {"sessions":1})
case("claude_stop", [step(0,"working","turn_start"),step(3000,"your_turn","turn_end", moments=["turn_end"])], {"turns":1,"working_seconds":3})
case("claude_interrupt_without_stop", [step(0,"working","turn_start","registry"),step(4000,"your_turn","turn_interrupted","registry","inferred",moments=[])], {"turns":0,"interrupted_turns":1,"working_seconds":4})
